#include <iostream>
using namespace std;

const int M = 1000003;

int head[M], nxt[100001], key[100001], val[100001], tot;

int h(int x) {
    return ((x % M) + M) % M;
}

void insert(int k, int v) {
    int pos = h(k);
    tot++;
    key[tot] = k;
    val[tot] = v;
    nxt[tot] = head[pos];
    head[pos] = tot;
}

int query(int k) {
    int pos = h(k);
    for (int i = head[pos]; i; i = nxt[i])
        if (key[i] == k) return val[i];
    return -1;
}

int main() {
    insert(12345, 100);
    insert(67890, 200);
    insert(1234567, 300);
    cout << "查询12345: " << query(12345) << endl;
    cout << "查询67890: " << query(67890) << endl;
    cout << "查询99999: " << query(99999) << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

const unsigned long long B = 13331;

unsigned long long h[100001], pw[100001];

void init(const string &s) {
    int n = s.size();
    pw[0] = 1;
    for (int i = 1; i <= n; i++) pw[i] = pw[i-1] * B;
    h[0] = 0;
    for (int i = 0; i < n; i++)
        h[i+1] = h[i] * B + s[i];
}

unsigned long long getHash(int l, int r) {
    return h[r+1] - h[l] * pw[r - l + 1];
}

int main() {
    string s;
    cin >> s;
    init(s);
    int q;
    cin >> q;
    while (q--) {
        int l1, r1, l2, r2;
        cin >> l1 >> r1 >> l2 >> r2;
        if (getHash(l1, r1) == getHash(l2, r2))
            cout << "相同" << endl;
        else
            cout << "不同" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

const int M = 1000003;

int table[M];
bool used[M];

int h1(int x) {
    return ((x % M) + M) % M;
}

int h2(int x) {
    return ((x % 999983) + 999983) % 999983 + 1;
}

void insertLinear(int x) {
    int pos = h1(x);
    while (used[pos]) pos = (pos + 1) % M;
    table[pos] = x;
    used[pos] = true;
}

bool searchLinear(int x) {
    int pos = h1(x);
    while (used[pos]) {
        if (table[pos] == x) return true;
        pos = (pos + 1) % M;
    }
    return false;
}

void insertDouble(int x) {
    int pos = h1(x);
    int step = h2(x);
    while (used[pos]) pos = (pos + step) % M;
    table[pos] = x;
    used[pos] = true;
}

bool searchDouble(int x) {
    int pos = h1(x);
    int step = h2(x);
    while (used[pos]) {
        if (table[pos] == x) return true;
        pos = (pos + step) % M;
    }
    return false;
}

int main() {
    insertLinear(12345);
    insertLinear(67890);
    insertLinear(1234567);
    cout << "线性探测查询12345: " << (searchLinear(12345) ? "找到" : "未找到") << endl;
    insertDouble(11111);
    insertDouble(22222);
    cout << "双重哈希查询11111: " << (searchDouble(11111) ? "找到" : "未找到") << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> disc;

int discretize(int x) {
    return lower_bound(disc.begin(), disc.end(), x) - disc.begin() + 1;
}

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        disc.push_back(a[i]);
    }
    sort(disc.begin(), disc.end());
    disc.erase(unique(disc.begin(), disc.end()), disc.end());
    cout << "离散化结果:" << endl;
    for (int i = 0; i < n; i++) {
        cout << a[i] << " -> " << discretize(a[i]) << endl;
    }
    cout << "去重后元素个数: " << disc.size() << endl;
    return 0;
}
